// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleBuildJobs) predicate.BundleBuildJobs {
	return predicate.BundleBuildJobs(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleBuildJobs) predicate.BundleBuildJobs {
	return predicate.BundleBuildJobs(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleBuildJobs) predicate.BundleBuildJobs {
	return predicate.BundleBuildJobs(sql.NotPredicates(p))
}
